package com.multitenanterp.payroll;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/payroll/runs") @PreAuthorize("@tenantAuthorization.hasAnyRole('SYSTEM_ADMIN','GROUP_ADMIN','COMPANY_ADMIN','PAYROLL_MANAGER','PAYROLL_EXECUTIVE')")
public class PayrollCalculationController{private final PayrollCalculationService service;public PayrollCalculationController(PayrollCalculationService service){this.service=service;}@PostMapping("/calculate") @ResponseStatus(HttpStatus.CREATED) public PayrollRun calculate(@Valid @RequestBody PayrollCalculationRequest request,Authentication authentication){return service.calculate(request.year(),request.month(),authentication.getName());}@GetMapping("/{year}/{month}") public PayrollRun get(@PathVariable int year,@PathVariable int month){return service.get(year,month);}@GetMapping("/{year}/{month}/variance") public List<PayrollVariance> variance(@PathVariable int year,@PathVariable int month){return service.variance(year,month);}@PutMapping("/{year}/{month}/exceptions/{exceptionId}/resolve") public PayrollException resolve(@PathVariable int year,@PathVariable int month,@PathVariable UUID exceptionId,@Valid @RequestBody ResolvePayrollExceptionRequest request,Authentication authentication){return service.resolveException(year,month,exceptionId,request.comment(),authentication.getName());}@PostMapping("/{year}/{month}/review") @PreAuthorize("@tenantAuthorization.hasAnyRole('SYSTEM_ADMIN','GROUP_ADMIN','COMPANY_ADMIN','PAYROLL_MANAGER')") public PayrollRun review(@PathVariable int year,@PathVariable int month,Authentication authentication){return service.startReview(year,month,authentication.getName());}}
